import {RHYTHMS} from './core.js';
export const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function icon(name){const paths={play:'<path d="m9 5 11 7-11 7Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',stop:'<rect x="6" y="6" width="12" height="12" rx="2"/>',plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',chevron:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m14 5-7 7 7 7"/>',save:'<path d="M12 3v12m-5-5 5 5 5-5M5 16v5h14v-5"/>',folder:'<path d="M3 7V4h6l2 3h10v13H3Z"/>',settings:'<path d="M5 3v18M12 3v18M19 3v18"/><path d="M2 8h6M9 16h6M16 9h6"/>',edit:'<path d="m4 16 12-12 4 4L8 20H4Zm10-10 4 4"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',undo:'<path d="M3 10h10a7 7 0 0 1 0 14M3 10l5-5M3 10l5 5"/>',redo:'<path d="M21 10H11a7 7 0 0 0 0 14m10-14-5-5m5 5-5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="2"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',headphones:'<path d="M4 14v-3a8 8 0 0 1 16 0v3"/><rect x="3" y="12" width="4" height="9" rx="2"/><rect x="17" y="12" width="4" height="9" rx="2"/>',music:'<path d="M9 18V5l11-2v13M9 9l11-2"/><ellipse cx="6" cy="18" rx="3" ry="3"/><ellipse cx="17" cy="16" rx="3" ry="3"/>',note:'<path d="M14 17V3l6 4"/><ellipse cx="10" cy="18" rx="4" ry="3"/>',shuffle:'<path d="M3 6h4l10 12h4m-4-4 4 4-4 4M3 18h4l4-5m3-4 3-3h4m-4-4 4 4-4 4"/>',home:'<path d="m3 10 9-7 9 7M5 8v13h5v-7h4v7h5V8"/>',expand:'<path d="M3 9V3h6m6 0h6v6m0 6v6h-6M9 21H3v-6"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 4 3c-1 1-1 1-1 3m0 2v1"/>',volume:'<path d="m11 4-6 5H2v6h3l6 5ZM15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',print:'<path d="M6 9V3h12v6M6 17H3V9h18v8h-3M6 14h12v7H6Z"/>',up:'<path d="m5 14 7-7 7 7"/>',down:'<path d="m5 10 7 7 7-7"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>'};return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.spark}</svg>`;}
function wrap(content,label,view='0 0 260 140'){return `<svg class="graphic" viewBox="${view}" role="img" aria-label="${escapeHTML(label)}" xmlns="http://www.w3.org/2000/svg">${content}</svg>`;}
export function graphic(g){if(!g)return '';const {kind,value}=g;
 if(kind==='dynamic'){const text=value==='crescendo'?'':value==='decrescendo'?'':value;return wrap(text?`<text x="130" y="96" text-anchor="middle" fill="currentColor" font-family="Georgia,serif" font-style="italic" font-weight="bold" font-size="90">${text}</text>`:`<path d="${value==='crescendo'?'M225 28 35 70 225 112':'M35 28 225 70 35 112'}" stroke="currentColor" stroke-width="4" fill="none"/>`,`${value} dynamic`);}
 if(kind==='note'){const step={C:0,D:1,E:2,F:3,G:4,A:5,B:6}[value[0]]+(Number(value[1])-4)*7;const y=108-step*7;let out='';for(let line=38;line<=94;line+=14)out+=`<path d="M20 ${line}h220" stroke="currentColor" stroke-width="1.4"/>`;out+='<text x="24" y="93" fill="currentColor" font-size="72" font-family="Noto Music,Segoe UI Symbol,serif">𝄞</text>';if(y>=108)out+='<path d="M124 108h44" stroke="currentColor" stroke-width="1.7"/>';out+=`<ellipse cx="146" cy="${y}" rx="12" ry="8" transform="rotate(-18 146 ${y})" fill="currentColor"/><path d="${step>=6?`M135 ${y}v43`:`M157 ${y}v-43`}" stroke="currentColor" stroke-width="3"/>`;return wrap(out,'Note on the treble staff');}
 if(kind==='rhythm'){const r=RHYTHMS.find(r=>r.id===value);if(!r)return '';let beat=0;const slots=r.beats.map(b=>{const d=typeof b==='number'?b:b.d;const n={x:20+(beat+d/2)*54,d,rest:typeof b==='object'&&b.rest};beat+=d;return n});let out='<path d="M10 96h240" stroke="currentColor" stroke-opacity=".2"/>';slots.forEach((n,i)=>{if(n.rest){out+=`<path d="m${n.x-4} 43 8 12-7 10 7 12-8 9q-10-9 0-14l-8-12 8-10Z" fill="currentColor"/>`;return;}out+=`<ellipse cx="${n.x}" cy="92" rx="8" ry="6" transform="rotate(-20 ${n.x} 92)" fill="${n.d>=2?'none':'currentColor'}" stroke="currentColor" stroke-width="2.3"/><path d="M${n.x+7} 90V44" stroke="currentColor" stroke-width="2.5"/>`;if(n.d===.5){const prev=slots[i-1];if(prev?.d===.5&&!prev.rest && i%2===1){/* beam handled by pair below */}const before=r.beats.slice(0,i).reduce((a,b)=>a+(typeof b==='number'?b:b.d),0);if(Number.isInteger(before)&&slots[i+1]?.d===.5){out+=`<path d="M${n.x+7} 46H${slots[i+1].x+7}" stroke="currentColor" stroke-width="6"/>`;}}});return wrap(out,'Four-beat rhythm');}
 if(kind==='instrument'){const paths={
 trumpet:'<path d="M38 68h117l40-29v65l-40-24H78q-32 0-32 26t36 20h61V76"/><path d="M89 67V47m20 20V45m21 22V47M80 47h18m2-2h18m3 2h18M24 63h17v16H24M82 84v25m27-25v25m21-25v25"/>',
 clarinet:'<path d="m125 13-6 16 4 8-5 65-13 23q24 11 50 0l-15-23-5-65 3-8-8-16Z"/><path d="M121 37h15m-16 59h20m-22 9h25"/><circle cx="128" cy="49" r="3"/><circle cx="129" cy="62" r="3"/><circle cx="129" cy="77" r="3"/><path d="M141 46v41m-4-36h10m-10 17h10m-10 15h10"/>',
 violin:'<path d="M124 40q-24-13-31 10-4 14 10 20-10 14-21 18-12 29 15 41 23 8 31-6 16 13 34 2 20-15 4-40-15-2-21-16 12-11 4-23-8-13-22-6"/><path d="M121 44V15h13v30m-11 68 1-88m6 88V25m-12-11q-8-12 4-14 21 0 14 14M106 74q-8-5-7 4l3 10m45-14q8-5 7 4l-3 10M113 99h28m-22 15h17l-7 10Z"/><path d="m192 12-7 117m-4-115-7 114"/>',
 timpani:'<path d="M42 60q4 63 88 64 83-2 88-64"/><ellipse cx="130" cy="58" rx="88" ry="20"/><path d="m76 116-7 19m117-19 7 19M46 61v15m167-15v15M81 57 53 15m113 39 31-38"/><circle cx="50" cy="12" r="7"/><circle cx="200" cy="12" r="7"/>',
 flute:'<path d="M27 63h206v15H27Z"/><path d="M59 63v15m129-15v15M31 70h12"/><circle cx="54" cy="68" r="3"/><circle cx="82" cy="71" r="5"/><circle cx="102" cy="71" r="5"/><circle cx="122" cy="71" r="5"/><circle cx="142" cy="71" r="5"/><circle cx="163" cy="71" r="5"/><circle cx="182" cy="71" r="5"/>',
 guitar:'<path d="M128 48q-19-16-34 1-10 13-4 24-24 9-21 33 0 34 48 31 42-1 43-26 4-28-20-36 9-22-4-26V18h-12v34"/><path d="m120 18-3-17h27l-5 17m-15 80V8m4 90V8m4 90V8m-18 105h28"/><circle cx="128" cy="86" r="12"/><path d="M113 7h8m18 0h8m-34 7h8m18 0h8"/>',
 xylophone:'<path d="M26 110 227 85v19L28 134Z"/><path d="m40 123 2 14m168-33 1 19"/><path d="M28 38h22v80H28Zm28 4h22v72H56Zm28 4h22v64H84Zm28 4h22v57h-22Zm28 4h22v48h-22Zm28 4h22v41h-22Zm28 4h22v32h-22Z"/><path d="m80 38-23-28m117 44 24-32"/><circle cx="53" cy="8" r="7"/><circle cx="202" cy="18" r="7"/>',
 drum:'<ellipse cx="130" cy="45" rx="74" ry="21"/><path d="M56 45v66q74 43 148 0V45M56 110q74 43 148 0M66 62l23 62 25-57 28 65 27-64 27 50M72 30 103 8m52 24 24-25"/>'
 };return wrap(`<g fill="none" stroke="currentColor" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round">${paths[value]||''}</g>`,value);}
 return '';
}
